package com.hrflow.entity; import jakarta.persistence.*;import lombok.*;import java.math.*;import java.time.*; @Entity @Getter @Setter @NoArgsConstructor @Table(name="payrolls",uniqueConstraints=@UniqueConstraint(columnNames={"employee_id","pay_month"})) public class Payroll { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) Long id; Long employeeId; String payMonth; BigDecimal basic=BigDecimal.ZERO,allowances=BigDecimal.ZERO,bonus=BigDecimal.ZERO,overtime=BigDecimal.ZERO,deductions=BigDecimal.ZERO,tax=BigDecimal.ZERO,gross=BigDecimal.ZERO,net=BigDecimal.ZERO; @Enumerated(EnumType.STRING) PayrollStatus status=PayrollStatus.DRAFT; Instant generatedAt=Instant.now(); Instant paidAt; }
